import{_ as n,C as t,o as r,c as s,E as a,a2 as d}from"./chunks/framework.BOeh4kYD.js";const l="/joinwell52/assets/current-authority-20260911/live-model-restore.figure.en.png",v=JSON.parse(`{"title":"Yesterday's Model Choice Is Not Today's Capability","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Yesterday's Model Choice Is Not Today's Capability","date":"2026-09-11","published_date":"2026-09-11","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Yesterday's Model Choice Is Not Today's Capability","summary":"Eight original-function comparisons distinguish an explicitly unsupported choice from an unavailable catalog during model restoration.","cover":"/assets/current-authority-20260911/live-model-restore.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded pinned-source experiments; no real cloud validation","pageClass":"current-authority-article"},"headers":[],"relativePath":"en/engineering/2026-09-11-live-model-restore.md","filePath":"en/engineering/2026-09-11-live-model-restore.md","lastUpdated":1789097107000}`),c={name:"en/engineering/2026-09-11-live-model-restore.md"};function h(p,e,u,g,m,f){const i=t("ArticleCover"),o=t("ArticleTableScroll");return r(),s("div",null,[a(i,{image:"/assets/current-authority-20260911/live-model-restore.cover-v1.png",kicker:"Open-source Engineering · Experiments",title:"Yesterday's Model Choice Is Not Today's Capability",summary:"Eight original-function comparisons distinguish an explicitly unsupported choice from an unavailable catalog during model restoration.",version:"2026-09-11",languageHref:"/zh/engineering/2026-09-11-live-model-restore",languageLabel:"中文"}),a(o,{language:"en"}),e[0]||(e[0]=d('<h1 id="yesterday-s-model-choice-is-not-today-s-capability" tabindex="-1">Yesterday&#39;s Model Choice Is Not Today&#39;s Capability <a class="header-anchor" href="#yesterday-s-model-choice-is-not-today-s-capability" aria-label="Permalink to &quot;Yesterday&#39;s Model Choice Is Not Today&#39;s Capability&quot;">​</a></h1><p>Remembering the last selected model is a natural product feature. What gets saved, however, is a preference. It cannot guarantee that the provider still offers the model today, or that the current account may use it.</p><p>The opposite case is harder: if today&#39;s model catalog cannot be read, should every saved choice be rejected? That apparently cautious rule could break working restoration on older clients.</p><p>An Orca candidate fix handles both cases at the same write boundary. We executed eight input conditions against its predecessor and candidate functions. The result was a deliberate distinction between negative evidence and missing evidence.</p><h2 id="accepting-a-setting-does-not-prove-useful-execution" tabindex="-1">Accepting a setting does not prove useful execution <a class="header-anchor" href="#accepting-a-setting-does-not-prove-useful-execution" aria-label="Permalink to &quot;Accepting a setting does not prove useful execution&quot;">​</a></h2><p>Orca is a desktop application that connects several agent execution tools. <a href="https://github.com/stablyai/orca/pull/19946" target="_blank" rel="noreferrer">PR #19946</a> reports a Claude structured-session experiment: setting an unlisted model ID can return successfully, while subsequent turns fail with zero tokens. Restoring a saved choice can reach the same path without a user typing an invalid value.</p><p>Those real-CLI observations belong to the upstream author. We did not launch Claude or reproduce those token measurements. Our question was narrower: does the proposed guard prevent <code>setModel</code> when the catalog explicitly excludes a choice, while preserving normal and compatibility paths?</p><p>The PR remained open when checked for this study. This is a candidate implementation, not a guarantee about a released desktop product.</p><h2 id="eight-conditions-measured-at-the-write-call" tabindex="-1">Eight conditions, measured at the write call <a class="header-anchor" href="#eight-conditions-measured-at-the-write-call" aria-label="Permalink to &quot;Eight conditions, measured at the write call&quot;">​</a></h2><p>We pinned baseline <code>027acb4efa2e6b226d40df266b86367423946d62</code> and candidate <code>a13c8452e70f214b50ea37149c6f6485bc149f6f</code>. Node 24.16.0 executed the original setting, restoration, and catalog-parsing function bodies after type stripping and explicit dependency injection. The connection was a test double returning controlled catalogs and recording calls.</p><p>This was not a complete desktop test. It measured whether the write method was called, whether the preference remained in state, and whether restoration recorded a skipped field. It did not observe real provider adoption or inference.</p><table tabindex="0"><thead><tr><th>Input and entry point</th><th style="text-align:right;">Baseline writes</th><th style="text-align:right;">Candidate writes</th><th>Candidate outcome</th></tr></thead><tbody><tr><td>Unlisted model, interactive change</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td>Rejected with the requested model name</td></tr><tr><td>Retired saved model, restore</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td>Model skipped; stale preference removed</td></tr><tr><td>Listed model alias</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>Write allowed</td></tr><tr><td>Resolved ID carried by an alias row</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>Write allowed</td></tr><tr><td>Catalog query throws</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>Compatibility path retained</td></tr><tr><td>Empty catalog</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>Compatibility path retained</td></tr><tr><td>Only a synthetic default row</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>Compatibility path retained</td></tr><tr><td>Listed model, restore</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>Normal restoration</td></tr></tbody></table><p>Eight conditions across two versions produced sixteen observations. The first two rows establish the meaningful change: explicit absence prevented the write. The remaining paths still reached the write method, including valid restoration.</p><p><img src="'+l+'" alt="Three outcomes for positive, negative, and unavailable catalog evidence"></p><p><em>Figure 1. Catalog evidence and the write decision. Source: this study&#39;s runs/orca.json. “Write allowed” means execution reached setModel; it does not establish account entitlement or successful inference.</em></p><h2 id="unknown-is-not-another-name-for-unsupported" tabindex="-1">Unknown is not another name for unsupported <a class="header-anchor" href="#unknown-is-not-another-name-for-unsupported" aria-label="Permalink to &quot;Unknown is not another name for unsupported&quot;">​</a></h2><p>A usable catalog that lists available choices but omits a saved ID provides a specific basis for refusal. An unavailable interface, failed query, or catalog with no identifiable models does not provide the same evidence.</p><p>The candidate retains compatibility in those latter cases. It does not certify the requested model as supported; it simply does not prohibit the write on this catalog check. Later behavior can still succeed or fail elsewhere.</p><p>Restoration makes the distinction consequential. An interactive refusal can be shown to the user. The restore function catches that refusal type, records the field as skipped, and removes the stale preference from <code>options</code>. Treating every unavailable catalog as negative evidence could silently discard otherwise usable choices on an older CLI.</p><p>This is not a general recommendation to permit actions whenever a security check fails. The boundary here is model-catalog compatibility, not secret access, spending authority, or permission for an external write. Each needs its own policy for unavailable evidence.</p><p>Aliases introduce another necessary distinction. A catalog row named <code>sonnet</code> may carry a complete <code>resolvedModel</code> ID. A saved complete ID should still match that listed option. Our alias control preserved that normal path.</p><h2 id="discovery-eligibility-and-adoption-ask-different-questions" tabindex="-1">Discovery, eligibility, and adoption ask different questions <a class="header-anchor" href="#discovery-eligibility-and-adoption-ask-different-questions" aria-label="Permalink to &quot;Discovery, eligibility, and adoption ask different questions&quot;">​</a></h2><p><a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/2127" target="_blank" rel="noreferrer">MCP Server Cards proposal #2127</a> makes a related design choice: static cards describe remote identity, connection details, and protocol versions, while omitting dynamic tool and capability claims. Its text was marked Final while its PR remained open; it is an optional extension-track proposal.</p><p>The implementations address different boundaries. MCP concerns pre-connection discovery; Orca concerns a particular model-setting operation. Both nevertheless expose the risk of letting a stored declaration answer a present-tense capability question.</p><p>A listed model still leaves account eligibility and actual provider adoption unresolved. The current credential may lack entitlement. A successful setter call may not establish useful execution. Catalog membership, setter return, and successful inference are different observations. This study tested the first check&#39;s effect on whether a write was attempted.</p><p>The comparison suggests a next experiment: find an inspectable observation of actual adoption. Would model-usage metadata from a successful turn suffice, or is a more direct provider confirmation needed? The upstream report notes that even an invalid model can appear in the init frame, so an echoed ID alone is insufficient. A live experiment could compare the requested model, initialization information, and model records from successful turns to test their agreement and whether fallback is observable. We have not run that experiment or established a silent-fallback defect.</p><h2 id="preserve-intent-while-allowing-preferences-to-expire" tabindex="-1">Preserve intent while allowing preferences to expire <a class="header-anchor" href="#preserve-intent-while-allowing-preferences-to-expire" aria-label="Permalink to &quot;Preserve intent while allowing preferences to expire&quot;">​</a></h2><p>For an agent client, begin with three acceptance categories: restore normally when current catalog evidence supports the choice; prevent the write and explain the skipped preference when it excludes the choice; follow an explicit compatibility policy when evidence is unavailable. Add controls for aliases versus resolved IDs and interactive changes versus startup restoration.</p><p>For CodeFlowMu/FCoP, this contract is now development-review input. Product review still needs to locate current Host catalog retrieval, account eligibility checks, adoption evidence, and explanations for skipped settings. We have not established a corresponding product defect or prescribed a new capability-snapshot table as the solution.</p><p>Useful restoration preserves user intent while recognizing that the environment can change. Yesterday&#39;s choice is a candidate. Today&#39;s applicable evidence determines what can still be used.</p><p>The <a href="./../research/evidence/2026-09-11-current-authority">evidence package</a> includes scripts, all sixteen observations, and limitations. Materials are maintained in the <a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">research repository</a>.</p>',31))])}const b=n(c,[["render",h]]);export{v as __pageData,b as default};
